#!/usr/bin/env python3
"""Analyze BIEK CS past papers CSV and generate an HTML trend analysis report."""

import csv
import re
import json
from collections import Counter, defaultdict
from pathlib import Path

# ── Load data ────────────────────────────────────────────────────────────────
DATA_PATH = "/app/benchmark/data.csv"
rows = []
with open(DATA_PATH, "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        r["year"] = int(r["year"])
        r["type"] = r["type"].strip()
        r["question"] = r["question"].strip()
        rows.append(r)

TOTAL_ROWS = len(rows)
YEARS = sorted(set(r["year"] for r in rows))
TYPES = ["MCQs", "Short", "Long"]

# ── 1. Overview ─────────────────────────────────────────────────────────────
type_counts = Counter(r["type"] for r in rows)
year_counts = Counter(r["year"] for r in rows)

# ── 2. Year-by-year breakdown ───────────────────────────────────────────────
yearly = {}
for y in YEARS:
    yearly[y] = {t: 0 for t in TYPES}
for r in rows:
    yearly[r["year"]][r["type"]] += 1

yearly_total = {y: sum(v.values()) for y, v in yearly.items()}

