}

# Word frequency overall
all_words = []
topic_by_type = {t: [] for t in TYPES}
topic_by_year = {y: [] for y in YEARS}

for r in rows:
    cleaned = clean_question(r["question"])
    words = [w.lower() for w in cleaned.split() if len(w) > 2 and w.lower() not in STOP_WORDS]
    all_words.extend(words)
    topic_by_type[r["type"]].extend(words)
    topic_by_year[r["year"]].extend(words)

word_freq = Counter(all_words)
top_keywords = word_freq.most_common(60)

# Topic by type
topic_type_freq = {t: Counter(topic_by_type[t]).most_common(15) for t in TYPES}

