#!/usr/bin/env python3
"""Analyze BIEK CS past papers CSV and generate an HTML trend analysis report."""

import csv
import re
import json
from collections import Counter, defaultdict
from pathlib import Path

# ── Load data ────────────────────────────────────────────────────────────────
DATA_PATH = "/app/benchmark/data.csv"
rows = []
with open(DATA_PATH, "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        r["year"] = int(r["year"])
        r["type"] = r["type"].strip()
        r["question"] = r["question"].strip()
        rows.append(r)

TOTAL_ROWS = len(rows)
YEARS = sorted(set(r["year"] for r in rows))
TYPES = ["MCQs", "Short", "Long"]

# ── 1. Overview ─────────────────────────────────────────────────────────────
type_counts = Counter(r["type"] for r in rows)
year_counts = Counter(r["year"] for r in rows)

# ── 2. Year-by-year breakdown ───────────────────────────────────────────────
yearly = {}
for y in YEARS:
    yearly[y] = {t: 0 for t in TYPES}
for r in rows:
    yearly[r["year"]][r["type"]] += 1

yearly_total = {y: sum(v.values()) for y, v in yearly.items()}

# ── 3. Question type ratios ─────────────────────────────────────────────────
yearly_pct = {}
for y in YEARS:
    tot = yearly_total[y]
    yearly_pct[y] = {t: round(yearly[y][t] / tot * 100, 1) for t in TYPES}

overall_pct = {t: round(type_counts[t] / TOTAL_ROWS * 100, 1) for t in TYPES}

# ── 4. YoY Change ───────────────────────────────────────────────────────────
yoy_abs = {}
yoy_pct = {}
for i in range(1, len(YEARS)):
    prev, curr = YEARS[i-1], YEARS[i]
    prev_tot = yearly_total[prev]
    curr_tot = yearly_total[curr]
    yoy_abs[curr] = curr_tot - prev_tot
    if prev_tot > 0:
        yoy_pct[curr] = round((curr_tot - prev_tot) / prev_tot * 100, 1)
    else:
        yoy_pct[curr] = 0

# ── 5. Averages per type ────────────────────────────────────────────────────
avg_per_type = {}
total_per_type = {t: sum(yearly[y][t] for y in YEARS) for t in TYPES}
avg_per_type = {t: round(total_per_type[t] / len(YEARS), 1) for t in TYPES}

# ── 6. Topic/Keyword analysis ───────────────────────────────────────────────
# Preprocess: remove $ delimiters, strip punctuation but keep words
def clean_question(text):
    # Replace $ with space
    text = text.replace("$", " ")
    # Remove parenthesized options like (a), (b), etc and Roman numerals
    text = re.sub(r'\([ivxlcdm]+\)', ' ', text, flags=re.IGNORECASE)
    # Remove special chars but keep letters, digits, spaces
    text = re.sub(r'[^a-zA-Z0-9\s]', ' ', text)
    # Collapse whitespace
    text = re.sub(r'\s+', ' ', text).strip()
    return text

STOP_WORDS = {
    'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'shall',
    'should', 'may', 'might', 'must', 'can', 'could', 'of', 'in', 'to',
    'for', 'with', 'on', 'at', 'by', 'from', 'or', 'and', 'not', 'this',
