    "Error Types": ["syntax error", "logical error", "runtime error", "debug"],
}

cat_year_counts = {}
for cat, terms in CATEGORIES.items():
    cat_year_counts[cat] = {}
    for y in YEARS:
        year_text = " ".join(topic_by_year[y]).lower()
        count = sum(year_text.count(t) for t in terms)
        cat_year_counts[cat][y] = count

# ── Identify emerging/late topics ───────────────────────────────────────────
early_years = [2015, 2016, 2017]
late_years = [2023, 2024, 2025]

early_text = " ".join(topic_by_year[y] for y in early_years).lower()
late_text = " ".join(topic_by_year[y] for y in late_years).lower()

emerging = []
declining = []
for concept in TRACK_CONCEPTS:
    early_count = sum(1 for y in early_years for _ in range(topic_year_trend[concept][y]))
    late_count = sum(1 for y in late_years for _ in range(topic_year_trend[concept][y]))
    if late_count > early_count * 1.5:
        emerging.append(concept)
    elif early_count > late_count * 1.5:
        declining.append(concept)

# ── 9. Generate HTML Report ─────────────────────────────────────────────────

def make_yearly_table():
    """Generate the yearly breakdown table."""
    rows_html = ""
    for y in YEARS:
        tot = yearly_total[y]
        rows_html += f"""
        <tr>
            <td>{y}</td>
