        if y not in yoy_abs:
            continue
        direction = "increase" if yoy_abs[y] >= 0 else "decrease"
        cls = "up" if yoy_abs[y] > 0 else "down" if yoy_abs[y] < 0 else "flat"
        cards += f"""<div class="kpi-card"><div class="kpi-year">{y}</div><div class="kpi-value {cls}">{yoy_abs[y]:+d} ({yoy_pct[y]:+}%)</div><div class="kpi-label">{direction}</div></div>"""
    return cards

# Data for Chart.js
yearly_data_json = json.dumps({str(y): yearly[y] for y in YEARS})
yearly_total_json = json.dumps({str(y): yearly_total[y] for y in YEARS})
yearly_pct_json = json.dumps({str(y): yearly_pct[y] for y in YEARS})
yoy_json = json.dumps({str(k): v for k, v in yoy_abs.items()})
top_words_json = json.dumps([{"word": w, "count": c} for w, c in top_keywords[:30]])
topic_trend_json = json.dumps(topic_year_trend)
TRACK_CONCEPTS_JSON = json.dumps(TRACK_CONCEPTS)
cat_year_json = json.dumps(cat_year_counts)
CATEGORIES_JSON = json.dumps(list(CATEGORIES.keys()))

# Highlight observations
def find_max_min_year(metric_dict):
    max_y = max(metric_dict, key=metric_dict.get)
    min_y = min(metric_dict, key=metric_dict.get)
    return max_y, metric_dict[max_y], min_y, metric_dict[min_y]

max_y, max_qt, min_y, min_qt = find_max_min_year(yearly_total)

# Stability metric: std dev of total questions as % of mean
import statistics
totals_list = [yearly_total[y] for y in YEARS]
mean_total = statistics.mean(totals_list)
std_total = statistics.stdev(totals_list)
cv = round(std_total / mean_total * 100, 1)

